// Em JavaScript pode lançar-se qualquer valor
function arriscar(n: number): void {
  if (n === 1) throw "texto";
  if (n === 2) throw 42;
  if (n === 3) throw {};
  throw new Error("falhou");
}

try {
  arriscar(1);
} catch (e) {
  // e: unknown (strict ativa useUnknownInCatchVariables)
  // @ts-expect-error TS18046: 'e' is of type 'unknown'
  console.log(e.message);
}

try {
  arriscar(2);
// @ts-expect-error TS1196: a anotação do catch só pode ser any ou unknown
} catch (e: Error) {
  console.log(e.message);
}

try {
  arriscar(3);
} catch (e: any) {
  // permitido, mas desliga a verificação: e.message compila sem aviso
  console.log(e.message);
}

// Na Promise o parâmetro do .catch é any (vem de lib.es5.d.ts)
Promise.reject(new Error("rejeitada")).catch((motivo) => {
  // motivo: any, apesar do strict: um erro de escrita passa sem aviso
  console.log(motivo.mesage); // undefined em runtime
});

// Anotar unknown à mão repõe a segurança
Promise.reject(new Error("rejeitada")).catch((motivo: unknown) => {
  // @ts-expect-error TS18046: 'motivo' is of type 'unknown'
  console.log(motivo.message);
});

function mensagemDe(e: unknown): string {
  if (e instanceof Error) return e.message;
  if (typeof e === "string") return e;
  if (typeof e === "object" && e !== null && "message" in e && typeof e.message === "string") {
    return e.message;
  }
  return `valor lançado não reconhecido: ${String(e)}`;
}

const lancamentos: (() => never)[] = [
  () => { throw new Error("disco cheio"); },
  () => { throw "sem permissão"; },
  () => { throw { message: "objeto com message" }; },
  () => { throw 42; },
];

for (const lancar of lancamentos) {
  try {
    lancar();
  } catch (e) {
    console.log(mensagemDe(e));
  }
}
// disco cheio
// sem permissão
// objeto com message
// valor lançado não reconhecido: 42

class ErroApp extends Error {
  constructor(mensagem: string, options?: ErrorOptions) {
    super(mensagem, options);
    this.name = new.target.name;
  }
}

class ErroValidacao extends ErroApp {
  constructor(
    public readonly campo: string,
    public readonly codigo: "obrigatorio" | "formato",
  ) {
    super(`campo ${campo} inválido (${codigo})`);
  }
}

class ErroNaoEncontrado extends ErroApp {
  constructor(public readonly id: number, options?: ErrorOptions) {
    super(`registo ${id} não existe`, options);
  }
}

function tratar(e: unknown): string {
  if (e instanceof ErroValidacao) return `${e.name}: ${e.campo} / ${e.codigo}`;
  if (e instanceof ErroNaoEncontrado) return `${e.name}: id ${e.id}`;
  if (e instanceof ErroApp) return `${e.name}: ${e.message}`;
  if (e instanceof Error) return `Error genérico: ${e.message}`;
  return "valor não-Error";
}

const casos: unknown[] = [
  new ErroValidacao("email", "formato"),
  new ErroNaoEncontrado(7),
  new ErroApp("falha da aplicação"),
  new TypeError("x is not a function"),
  "texto",
];
for (const c of casos) console.log(tratar(c));
// ErroValidacao: email / formato
// ErroNaoEncontrado: id 7
// ErroApp: falha da aplicação
// Error genérico: x is not a function
// valor não-Error

// A opção cause (ES2022) guarda o erro original
try {
  try {
    throw new Error("timeout na base de dados");
  } catch (original) {
    throw new ErroNaoEncontrado(7, { cause: original });
  }
} catch (e) {
  if (e instanceof Error) {
    const causa = e.cause; // causa: unknown
    console.log(e.message, "<-", causa instanceof Error ? causa.message : causa);
  }
}
// registo 7 não existe <- timeout na base de dados

type ErroDominio =
  | { tipo: "rede"; tentativas: number }
  | { tipo: "validacao"; campo: string }
  | { tipo: "naoEncontrado"; id: number };

function descrever(erro: ErroDominio): string {
  switch (erro.tipo) {
    case "rede":
      return `rede indisponível após ${erro.tentativas} tentativas`;
    case "validacao":
      return `campo inválido: ${erro.campo}`;
    case "naoEncontrado":
      return `não existe o registo ${erro.id}`;
    default: {
      const impossivel: never = erro;
      return impossivel;
    }
  }
}

const erros: ErroDominio[] = [
  { tipo: "rede", tentativas: 3 },
  { tipo: "validacao", campo: "nif" },
  { tipo: "naoEncontrado", id: 12 },
];
for (const e of erros) console.log(descrever(e));
// rede indisponível após 3 tentativas
// campo inválido: nif
// não existe o registo 12

type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

// Sem a anotação de retorno, { ok: true, valor } seria { ok: boolean; valor: T }
function ok<T>(valor: T): { ok: true; valor: T } {
  return { ok: true, valor };
}
function falha<E>(erro: E): { ok: false; erro: E } {
  return { ok: false, erro };
}

type ErroDivisao = "divisaoPorZero" | "naoFinito";

function dividir(a: number, b: number): Resultado<number, ErroDivisao> {
  if (b === 0) return falha("divisaoPorZero");
  const q = a / b;
  if (!Number.isFinite(q)) return falha("naoFinito");
  return ok(q);
}

for (const [a, b] of [[10, 4], [1, 0]] as const) {
  const r = dividir(a, b);
  if (r.ok) {
    console.log("valor:", r.valor); // r: { ok: true; valor: number }
  } else {
    console.log("erro:", r.erro); // r: { ok: false; erro: ErroDivisao }
  }
}
// valor: 2.5
// erro: divisaoPorZero

type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

async function tentar<T>(fn: () => Promise<T>): Promise<Resultado<T, Error>> {
  try {
    return { ok: true, valor: await fn() };
  } catch (e) {
    const erro = e instanceof Error ? e : new Error(String(e));
    return { ok: false, erro };
  }
}

// Simulação local de um serviço remoto (sem rede)
async function obterPreco(codigo: string): Promise<number> {
  if (codigo === "A1") return 19.9;
  throw new Error(`produto ${codigo} indisponível`);
}

const r1 = await tentar(() => obterPreco("A1"));
const r2 = await tentar(() => obterPreco("Z9"));

for (const r of [r1, r2]) {
  if (r.ok) console.log("preço:", r.valor);
  else console.log("falhou:", r.erro.message);
}
// preço: 19.9
// falhou: produto Z9 indisponível

