// A assinatura não revela que pode lançar
function lerPortaOuLancar(texto: string): number {
  const n = Number(texto);
  if (!Number.isInteger(n)) throw new RangeError(`porta inválida: ${texto}`);
  return n;
}

// Aqui o erro faz parte do tipo de retorno
function lerPorta(texto: string): Resultado<number, "naoInteiro"> {
  const n = Number(texto);
  return Number.isInteger(n) ? { ok: true, valor: n } : { ok: false, erro: "naoInteiro" };
}

try {
  console.log(lerPortaOuLancar("abc"));
} catch (e) {
  console.log(e instanceof RangeError ? e.message : "outro erro");
}
const r = lerPorta("abc");
console.log(r.ok ? r.valor : r.erro);
// porta inválida: abc
// naoInteiro

