function descreverErro(e: unknown): string {
  if (e instanceof Error) return `${e.name}: ${e.message}`;
  if (typeof e === "string") return `texto: ${e}`;
  if (typeof e === "number") return `número: ${e}`;
  return "desconhecido";
}

const testes: unknown[] = [new TypeError("mau tipo"), "ups", 404, null];
for (const t of testes) {
  try {
    throw t;
  } catch (e) {
    console.log(descreverErro(e));
  }
}
// TypeError: mau tipo
// texto: ups
// número: 404
// desconhecido

class ErroSaldo extends Error {
  constructor(
    public readonly saldo: number,
    public readonly pedido: number,
  ) {
    super(`saldo insuficiente: ${saldo} < ${pedido}`);
    this.name = "ErroSaldo";
  }
  get emFalta(): number {
    return this.pedido - this.saldo;
  }
}

function levantar(saldo: number, valor: number): number {
  if (valor <= 0) throw new RangeError("o valor tem de ser positivo");
  if (valor > saldo) throw new ErroSaldo(saldo, valor);
  return saldo - valor;
}

for (const valor of [30, 150, -5]) {
  try {
    console.log("novo saldo:", levantar(100, valor));
  } catch (e) {
    if (e instanceof ErroSaldo) console.log(`${e.name}: faltam ${e.emFalta}`);
    else if (e instanceof Error) console.log(`${e.name}: ${e.message}`);
    else console.log("erro desconhecido");
  }
}
// novo saldo: 70
// ErroSaldo: faltam 50
// RangeError: o valor tem de ser positivo

type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

type ErroIdade =
  | { tipo: "vazio" }
  | { tipo: "naoNumero"; texto: string }
  | { tipo: "foraDoIntervalo"; valor: number };

function lerIdade(texto: string): Resultado<number, ErroIdade> {
  const limpo = texto.trim();
  if (limpo === "") return { ok: false, erro: { tipo: "vazio" } };
  const n = Number(limpo);
  if (!Number.isInteger(n)) return { ok: false, erro: { tipo: "naoNumero", texto: limpo } };
  if (n < 0 || n > 130) return { ok: false, erro: { tipo: "foraDoIntervalo", valor: n } };
  return { ok: true, valor: n };
}

function explicar(erro: ErroIdade): string {
  switch (erro.tipo) {
    case "vazio":
      return "a idade é obrigatória";
    case "naoNumero":
      return `"${erro.texto}" não é um número inteiro`;
    case "foraDoIntervalo":
      return `${erro.valor} está fora de 0 a 130`;
    default: {
      const impossivel: never = erro;
      return impossivel;
    }
  }
}

for (const entrada of ["42", "  ", "doze", "200"]) {
  const r = lerIdade(entrada);
  console.log(r.ok ? `idade ${r.valor}` : explicar(r.erro));
}
// idade 42
// a idade é obrigatória
// "doze" não é um número inteiro
// 200 está fora de 0 a 130

type Resultado<T, E> = { ok: true; valor: T } | { ok: false; erro: E };

type ErroServico =
  | { tipo: "rede"; mensagem: string }
  | { tipo: "desconhecido"; valor: unknown };

async function tentarCom<T, E>(
  fn: () => Promise<T>,
  mapear: (e: unknown) => E,
): Promise<Resultado<T, E>> {
  try {
    return { ok: true, valor: await fn() };
  } catch (e) {
    return { ok: false, erro: mapear(e) };
  }
}

function paraErroServico(e: unknown): ErroServico {
  if (e instanceof Error) return { tipo: "rede", mensagem: e.message };
  return { tipo: "desconhecido", valor: e };
}

// Serviço simulado localmente
async function obterStock(codigo: string): Promise<number> {
  if (codigo === "A1") return 12;
  if (codigo === "B2") throw new Error("ligação recusada");
  throw "código estranho";
}

for (const codigo of ["A1", "B2", "C3"]) {
  const r = await tentarCom(() => obterStock(codigo), paraErroServico);
  if (r.ok) {
    console.log(`${codigo}: ${r.valor} unidades`);
  } else if (r.erro.tipo === "rede") {
    console.log(`${codigo}: falha de rede (${r.erro.mensagem})`);
  } else {
    console.log(`${codigo}: erro desconhecido (${String(r.erro.valor)})`);
  }
}
// A1: 12 unidades
// B2: falha de rede (ligação recusada)
// C3: erro desconhecido (código estranho)
